import { Column } from '@tale-ui/react/column';
import { Link } from '@tale-ui/react/link';
import { PreviewCard } from '@tale-ui/react/preview-card';
import { Text } from '@tale-ui/react/text';

export function LinkWithPreviewCard() {
  return (
    <PreviewCard.Root>
      <PreviewCard.Trigger>
        <Link href="/release-notes">Release notes</Link>
      </PreviewCard.Trigger>
      <PreviewCard.Popup placement="bottom" offset={8}>
        <PreviewCard.Arrow />
        <PreviewCard.Content aria-label="Release notes preview">
          <Column gap="s" style={{ maxWidth: '18rem' }}>
            <Text variant="heading">Latest release</Text>
            <Text color="muted">A quick summary of the linked release notes.</Text>
          </Column>
        </PreviewCard.Content>
      </PreviewCard.Popup>
    </PreviewCard.Root>
  );
}
